package com.dappunq.persistence; import com.fasterxml.jackson.core.type.TypeReference; import com.fasterxml.jackson.databind.ObjectMapper; import com.dappunq.model.valuation.*; import org.springframework.stereotype.Component; import java.util.*; import java.math.*;
@Component public class ValuationPersistenceMapper { private final ObjectMapper mapper=new ObjectMapper(); public String write(Map<String,BigDecimal> m){try{return mapper.writeValueAsString(m);}catch(Exception e){throw new ValuationDomainException("Pesos invalidos");}} public Map<String,BigDecimal> read(String s){try{return mapper.readValue(s,new TypeReference<>(){});}catch(Exception e){throw new ValuationDomainException("Pesos invalidos");}} }
